package com.picalibrary.android;

import android.app.*;
import android.content.Intent;
import android.net.Uri;
import android.os.Bundle;
import android.view.Gravity;
import android.widget.*;
import java.util.Locale;

/** User-facing storage, prefetch and persistent-download policy. */
public final class StorageSettingsActivity extends Activity {
    private static final int PICK_DOWNLOAD_TREE=401;private LinearLayout content;
    @Override public void onCreate(Bundle saved){super.onCreate(saved);Ui.applyWindow(this);render();}
    private Button button(String label,android.view.View.OnClickListener action){return Ui.button(this,label,action,false);}
    private void render(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Ui.BG);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(0,i.getSystemWindowInsetTop(),0,i.getSystemWindowInsetBottom());return i;});LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.addView(Ui.button(this,"‹ 返回",v->finish(),true));bar.addView(Ui.text(this,"存储与预加载",22,Ui.TEXT,true),new LinearLayout.LayoutParams(0,-2,1));root.addView(bar);ScrollView scroll=new ScrollView(this);scroll.setBackgroundColor(Ui.BG);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(Ui.dp(this,12),Ui.dp(this,8),Ui.dp(this,12),Ui.dp(this,24));scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);root.requestApplyInsets();renderContent();}
    private void renderContent(){content.removeAllViews();StoragePolicy.Usage usage=StoragePolicy.usage(this);LinearLayout summary=Ui.card(this);summary.addView(Ui.text(this,"当前占用",18,Ui.TEXT,true));summary.addView(Ui.text(this,"阅读页 "+fmt(usage.pages)+" · 封面 "+fmt(usage.covers)+" · 元数据 "+fmt(usage.metadata)+"\n合计 "+fmt(usage.total),13,Ui.MUTED,false));content.addView(summary);LinearLayout pages=Ui.card(this);pages.addView(Ui.text(this,"阅读页缓存",18,Ui.TEXT,true));pages.addView(Ui.text(this,"当前上限："+StorageSettings.limitLabel(StorageSettings.pageMb(this)),13,Ui.MUTED,false));pages.addView(button("调整上限",v->chooseLong("阅读页缓存",StorageSettings.PAGE_MB,StorageSettings.pageMb(this),value->{StorageSettings.setPageMb(this,value);StoragePolicy.maintain(this);renderContent();})));content.addView(pages);LinearLayout covers=Ui.card(this);covers.addView(Ui.text(this,"封面缓存",18,Ui.TEXT,true));covers.addView(Ui.text(this,"当前上限："+StorageSettings.limitLabel(StorageSettings.coverMb(this)),13,Ui.MUTED,false));covers.addView(button("调整上限",v->chooseLong("封面缓存",StorageSettings.COVER_MB,StorageSettings.coverMb(this),value->{StorageSettings.setCoverMb(this,value);StoragePolicy.maintain(this);renderContent();})));content.addView(covers);LinearLayout prefetch=Ui.card(this);prefetch.addView(Ui.text(this,"阅读预加载",18,Ui.TEXT,true));prefetch.addView(Ui.text(this,"当前：提前 "+StorageSettings.prefetchPages(this)+" 页",13,Ui.MUTED,false));prefetch.addView(button("调整预加载",v->choosePrefetch()));content.addView(prefetch);LinearLayout roots=Ui.card(this);roots.addView(Ui.text(this,"存储位置",18,Ui.TEXT,true));roots.addView(Ui.text(this,"应用数据："+(StorageSettings.dataExternal(this)?"外部存储":"内部存储")+"\n缓存："+(StorageSettings.cacheExternal(this)?"外部存储":"内部存储"),13,Ui.MUTED,false));LinearLayout rootActions=new LinearLayout(this);rootActions.addView(button("应用数据",v->chooseDataRoot()),new LinearLayout.LayoutParams(0,-2,1));Ui.gap(rootActions,this,8);rootActions.addView(button("缓存位置",v->chooseCacheRoot()),new LinearLayout.LayoutParams(0,-2,1));roots.addView(rootActions);content.addView(roots);LinearLayout downloads=Ui.card(this);downloads.addView(Ui.text(this,"手机下载",18,Ui.TEXT,true));String tree=StorageSettings.downloadTreeUri(this);downloads.addView(Ui.text(this,(tree.isEmpty()?"默认下载目录":"自定义下载目录")+" · "+(StorageSettings.downloadWifiOnly(this)?"仅 Wi‑Fi":"允许移动网络"),12,Ui.MUTED,false));downloads.addView(button("选择下载文件夹",v->pickDownloadTree()));Ui.gap(downloads,this,8);downloads.addView(button(StorageSettings.downloadWifiOnly(this)?"允许移动网络":"仅 Wi‑Fi 下载",v->{StorageSettings.setDownloadWifiOnly(this,!StorageSettings.downloadWifiOnly(this));renderContent();}));content.addView(downloads);LinearLayout clean=Ui.card(this);clean.addView(Ui.text(this,"清理缓存",18,Ui.TEXT,true));LinearLayout row=new LinearLayout(this);row.addView(button("清阅读页",v->{StoragePolicy.clearPages(this);renderContent();}),new LinearLayout.LayoutParams(0,-2,1));Ui.gap(row,this,8);row.addView(button("清封面",v->{StoragePolicy.clearCovers(this);renderContent();}),new LinearLayout.LayoutParams(0,-2,1));clean.addView(row);Ui.gap(clean,this,8);clean.addView(button("清元数据缓存",v->new AlertDialog.Builder(this).setTitle("清理元数据缓存？").setMessage("不会删除手机下载、云端漫画或账号。") .setNegativeButton("取消",null).setPositiveButton("清理",(d,w)->{StoragePolicy.clearMetadata(this);renderContent();}).show()));content.addView(clean);}
    private interface LongChoice{void selected(long value);}
    private void chooseLong(String title,long[] values,long current,LongChoice choice){String[] labels=new String[values.length];int selected=0;for(int i=0;i<values.length;i++){labels[i]=StorageSettings.limitLabel(values[i]);if(values[i]==current)selected=i;}final int initial=selected;new AlertDialog.Builder(this).setTitle(title).setSingleChoiceItems(labels,selected,null).setNegativeButton("取消",null).setPositiveButton("保存",(d,w)->{int index=((AlertDialog)d).getListView().getCheckedItemPosition();if(index<0)index=initial;choice.selected(values[index]);}).show();}
    private void choosePrefetch(){int[] values=StorageSettings.PREFETCH;String[] labels=new String[values.length];int selected=0,current=StorageSettings.prefetchPages(this);for(int i=0;i<values.length;i++){labels[i]=values[i]==0?"关闭":values[i]+" 页";if(values[i]==current)selected=i;}final int initial=selected;new AlertDialog.Builder(this).setTitle("页面预加载").setSingleChoiceItems(labels,selected,null).setNegativeButton("取消",null).setPositiveButton("保存",(d,w)->{int index=((AlertDialog)d).getListView().getCheckedItemPosition();if(index<0)index=initial;StorageSettings.setPrefetchPages(this,values[index]);renderContent();}).show();}
    private void chooseDataRoot(){if(!MobileStoragePaths.externalAvailable(this)){Toast.makeText(this,"当前没有可用的外部存储",Toast.LENGTH_LONG).show();return;}String[] labels={"内部存储（推荐）","外部存储"};int selected=StorageSettings.dataExternal(this)?1:0;new AlertDialog.Builder(this).setTitle("应用数据位置").setSingleChoiceItems(labels,selected,null).setNegativeButton("取消",null).setPositiveButton("迁移",(d,w)->{int index=((AlertDialog)d).getListView().getCheckedItemPosition();try{MobileStoragePaths.migrateDataRoot(this,index==1);renderContent();}catch(Exception e){Toast.makeText(this,"迁移失败："+e.getMessage(),Toast.LENGTH_LONG).show();}}).show();}
    private void chooseCacheRoot(){if(!MobileStoragePaths.externalAvailable(this)){Toast.makeText(this,"当前没有可用的外部存储",Toast.LENGTH_LONG).show();return;}String[] labels={"内部存储","外部存储"};int selected=StorageSettings.cacheExternal(this)?1:0;new AlertDialog.Builder(this).setTitle("缓存位置").setMessage("切换时会清理现有阅读页和封面缓存，不会删除已下载漫画。") .setSingleChoiceItems(labels,selected,null).setNegativeButton("取消",null).setPositiveButton("切换",(d,w)->{int index=((AlertDialog)d).getListView().getCheckedItemPosition();boolean external=index==1;if(external==StorageSettings.cacheExternal(this)){renderContent();return;}StoragePolicy.clearPages(this);StoragePolicy.clearCovers(this);StorageSettings.setCacheExternal(this,external);StoragePolicy.maintain(this);renderContent();}).show();}
    private void pickDownloadTree(){Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(intent,PICK_DOWNLOAD_TREE);}
    @Override protected void onActivityResult(int requestCode,int resultCode,Intent data){super.onActivityResult(requestCode,resultCode,data);if(requestCode!=PICK_DOWNLOAD_TREE||resultCode!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();int granted=data.getFlags();boolean read=(granted&Intent.FLAG_GRANT_READ_URI_PERMISSION)!=0;boolean write=(granted&Intent.FLAG_GRANT_WRITE_URI_PERMISSION)!=0;try{if(read&&write)getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);else if(read)getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);else if(write)getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_WRITE_URI_PERMISSION);}catch(Exception ignored){}StorageSettings.setDownloadTreeUri(this,uri.toString());renderContent();}
    private String fmt(long value){if(value<1024)return value+" B";if(value<1024L*1024)return String.format(Locale.ROOT,"%.1f KB",value/1024.0);if(value<1024L*1024*1024)return String.format(Locale.ROOT,"%.1f MB",value/1024.0/1024.0);return String.format(Locale.ROOT,"%.2f GB",value/1024.0/1024.0/1024.0);}
}
